using UnityEngine; namespace SkiStation { public class SlopeWeatherRuntime:MonoBehaviour { public float accumulation,quality=1f; public bool visibilityLimited; void Update(){if(WeatherRuntime.I==null)return;var w=WeatherRuntime.I.Current;quality=w.snowQualityModifier;visibilityLimited=w.visibility<.75f;if(w.condition==WeatherCondition.FreshSnow||w.condition==WeatherCondition.Snowfall)accumulation+=w.snowfallCm*Time.deltaTime/60f;if(w.condition==WeatherCondition.Thaw||w.condition==WeatherCondition.Rain)accumulation=Mathf.Max(0,accumulation-Time.deltaTime*.01f);} } }
